using System;
using System.Collections.Generic;
using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "OnStatusDiceDrawOmenData", menuName = "Data/Battle/Omens System/Omen Data/Moonie/OnStatusDiceDraw Omen Data")]
public class OnStatusDiceDrawOmenData : OmenData
{
	[Header("OnStartOfTurn Omen")]
	[SerializeField]
	private DiceTier diceTier;

	private Action<List<Dice>> omenAction;

	private OmenInstance omenInstance;

	public override void Initialize(OmenInstance omenInstance)
	{
		omenAction = (EnableOmenCounter ? OmenWithCounterAction(omenInstance) : OmenNoCounterAction(omenInstance));
		ReferenceSingleton<MiscOmensHandler>.Instance.OnStatusDiceDrawnOmenActions.Add(omenAction);
		if (!KeepOmenCounterBetweenBattles)
		{
			ReferenceSingleton<StartBattleStartEndTurnOmensHandler>.Instance.RestartEndBattleOmens.Add(omenInstance);
			this.omenInstance = omenInstance;
		}
	}

	private Action<List<Dice>> OmenWithCounterAction(OmenInstance omenInstance)
	{
		return delegate(List<Dice> diceList)
		{
			int num = 0;
			for (int i = 0; i < diceList.Count; i++)
			{
				if (IsStatusDice(diceList[i]))
				{
					num++;
				}
			}
			if (OmenWillTrigger(num))
			{
				omenInstance.EnqueueOmenFeedbackAndPlay();
				omenInstance.StopBlinkingFeedback();
			}
			for (int j = 0; j < diceList.Count; j++)
			{
				if (IsStatusDice(diceList[j]))
				{
					ActivateOmen();
					omenInstance.UpdateOmenCounter();
				}
			}
			if (OmenAboutToTrigger())
			{
				omenInstance.PlayBlinkingFeedback();
			}
		};
	}

	private bool OmenWillTrigger(int statusDiceAmount)
	{
		return counter + statusDiceAmount >= TriggerAmount;
	}

	private bool OmenAboutToTrigger()
	{
		return counter == TriggerAmount - 1;
	}

	private Action<List<Dice>> OmenNoCounterAction(OmenInstance omenInstance)
	{
		return delegate(List<Dice> diceList)
		{
			bool flag = false;
			for (int i = 0; i < diceList.Count; i++)
			{
				if (IsStatusDice(diceList[i]))
				{
					flag = true;
				}
			}
			if (flag)
			{
				omenInstance.EnqueueOmenFeedbackAndPlay();
			}
			for (int j = 0; j < diceList.Count; j++)
			{
				if (IsStatusDice(diceList[j]))
				{
					ActivateOmen();
				}
			}
		};
	}

	private bool IsStatusDice(Dice dice)
	{
		return dice.DiceTier == diceTier;
	}

	public override void OmenRemoved()
	{
		ReferenceSingleton<MiscOmensHandler>.Instance.OnStatusDiceDrawnOmenActions.Remove(omenAction);
		if (!KeepOmenCounterBetweenBattles)
		{
			ReferenceSingleton<StartBattleStartEndTurnOmensHandler>.Instance.RestartEndBattleOmens.Remove(omenInstance);
			omenInstance = null;
		}
	}
}
